void QuotaCases(){
 for(unsigned extra=0;extra<2;++extra){auto spec=CloneSpec(1);Fixture base(spec);spec.volumes[0].quota_block_count=base.checkpoint.volumes[0].superblock.space.allocated_block_count+extra;Fixture f(spec);auto name="quota-cow-"+std::to_string(extra);auto path=std::filesystem::absolute(name+".apfs");Save(path,f.image);auto c=Context(path);Store store(c);Check(store.PrepareNativeWritePath(),"quota source opens");auto xid=*store.CheckpointXid();Tx tx(L"Strict");tx.SetJournalPath(std::filesystem::absolute(name+".wal").wstring());tx.SetVolumeIdentity(L"quota");Store::CloneReceipt receipt;
  const auto accepted=store.AcceptNativeClone(tx,L"\\clone0",L"\\new",receipt);if(accepted!=Store::CloneAcceptance::Accepted)std::wcerr<<L"quota clone admission "<<store.LastCommitFailureReason()<<L" "<<store.LastCommitFailureDetail()<<L"\n";
  Check(accepted==Store::CloneAcceptance::Accepted,"sharing clone consumes no payload quota");Check(store.CommitPendingMutations({xid})==Store::CommitStatus::Committed,"ordinary commit path publishes accepted clone under tight quota");
  Store::MutationRequest write;write.path=L"\\new";write.offset=kBlockSize+5;write.length=29;
  const auto before=Disk(path);const auto pending=store.PendingMutationCount();unsigned calls=0;auto expected=Payload(f,17);std::fill_n(expected.begin()+write.offset,write.length,std::byte{0x66});store.SetFilePayloadRangeProvider([&](const auto&,auto,auto at,std::span<std::byte>b){++calls;std::copy_n(expected.begin()+at,b.size(),b.begin());return true;});
  const auto preview=store.PreflightNativeCapacityMutation(write,{xid});Check(calls==0&&store.PendingMutationCount()==pending&&Disk(path)==before,"first COW quota preview restores state without payload calls");
  Check(preview==(extra?Store::MutationStatus::Applied:Store::MutationStatus::CapacityBlocked),"tight quota predicts one-block shared first COW outcome");
  Check(store.StageMutation(write)==Store::MutationStatus::Applied,"COW stages for commit comparison");const auto committed=store.CommitPendingMutations({xid});Check(committed==(extra?Store::CommitStatus::Committed:Store::CommitStatus::CapacityBlocked),"commit quota outcome matches preview");
  if(!extra)Check(Disk(path)==before&&store.PendingMutationCount()==1,"quota refusal retains accepted source and pending COW for retry");
 }
 auto spec=CloneSpec(1);std::string error;for(auto& r:spec.volumes[0].filesystem_records)if(Type(r)==4){AppleXattrRecord a;Check(ApfsExtendedRecordCodec::DecodeXattr(r,a,error),error);a.data.resize(2300,std::byte{0x67});Check(EncodeAppleXattrRecord(a,r,error),error);}
 Fixture base(spec);spec.volumes[0].quota_block_count=base.checkpoint.volumes[0].superblock.space.allocated_block_count;Fixture f(spec);auto path=std::filesystem::absolute("quota-admission.apfs");Save(path,f.image);Store store(Context(path));Check(store.PrepareNativeWritePath(),"metadata quota fixture opens");Store::MutationRequest before,after;Check(store.PrepareNativeClone(L"\\clone0",L"\\new",before),"metadata quota source is supported");Tx tx(L"Strict");tx.SetJournalPath(std::filesystem::absolute("quota-admission.wal").wstring());tx.SetVolumeIdentity(L"quota-admission");Store::CloneReceipt receipt;Check(store.AcceptNativeClone(tx,L"\\clone0",L"\\new",receipt)==Store::CloneAcceptance::Refused,"native metadata quota refusal occurs before acceptance");Check(tx.Watermarks().accepted_sequence==0&&store.PendingMutationCount()==0&&!store.LookupWorkingInodeByPath(L"\\new")&&Disk(path)==f.image,"quota admission refusal is atomic");Check(store.PrepareNativeClone(L"\\clone0",L"\\new",after)&&before.object_id==after.object_id&&before.inline_payload==after.inline_payload,"refused clone reuses exactly same inode allocation and proof");
}
